"""
seed_demo_data — a demo library: users (one per role), sample PDFs with real
storage keys, metadata, a shared reading room with sample annotations (incl. a
reply thread), bookmarks, progress and a review.

Idempotent: re-running updates rather than duplicating (natural keys).

Usage:
    python manage.py seed_demo_data
"""
from django.core.files.base import ContentFile
from django.core.management.base import BaseCommand

# Two small but valid multi-page PDFs, generated byte-exact (see samples/).
SAMPLE_PDFS = {
    "books/seed-handbook.pdf": None,   # filled at runtime by _make_pdf
    "books/seed-notes.pdf": None,
}


def _make_pdf(pages: int, title: str) -> bytes:
    """Build a minimal valid PDF with `pages` blank pages and a title."""
    objects = []
    objects.append(b"<< /Type /Catalog /Pages 2 0 R >>")
    kids = " ".join(f"{3 + i} 0 R" for i in range(pages))
    objects.append(f"<< /Type /Pages /Kids [{kids}] /Count {pages} >>".encode())
    for i in range(pages):
        objects.append(
            f"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] "
            f"/Resources << /Font << /F1 {3 + pages} 0 R >> >> "
            f"/Contents {3 + pages + 1 + i} 0 R >>".encode()
        )
    objects.append(b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>")
    for i in range(pages):
        stream = f"BT /F1 24 Tf 72 720 Td ({title} - page {i + 1}) Tj ET".encode()
        objects.append(
            f"<< /Length {len(stream)} >>\nstream\n".encode() + stream + b"\nendstream"
        )

    out = bytearray(b"%PDF-1.4\n")
    offsets = [0]
    for i, obj in enumerate(objects, start=1):
        offsets.append(len(out))
        out += f"{i} 0 obj\n".encode() + obj + b"\nendobj\n"
    xref_at = len(out)
    out += f"xref\n0 {len(objects) + 1}\n".encode()
    out += b"0000000000 65535 f \n"
    for off in offsets[1:]:
        out += f"{off:010d} 00000 n \n".encode()
    out += (
        f"trailer << /Size {len(objects) + 1} /Root 1 0 R "
        f"/Info << /Title ({title}) /Author (Marginalia Seed) >> >>\n"
        f"startxref\n{xref_at}\n%%EOF\n"
    ).encode()
    return bytes(out)


class Command(BaseCommand):
    help = "Seed demo users, books, annotations and a shared reading room."

    def handle(self, *args, **options):
        from apps.accounts.models import Profile, Role
        from apps.annotations.models import Annotation
        from apps.authors.models import Author
        from apps.collections.models import Collection, Visibility
        from apps.library.models import Book, Category
        from apps.reading.models import ReadingProgress, Review
        from apps.rooms.models import ReadingRoom, RoomMember, RoomRole
        from apps.series.models import Series
        from django.contrib.auth import get_user_model

        User = get_user_model()

        users = {}
        for username, role, display in [
            ("ada", Role.ADMIN, "Ada Lovelace"),
            ("libby", Role.LIBRARIAN, "Libby Brant"),
            ("milo", Role.MEMBER, "Milo Vance"),
            ("noor", Role.MEMBER, "Noor Hassan"),
        ]:
            user, _ = User.objects.get_or_create(username=username)
            user.set_password("demo-password-123")
            user.save()
            profile, _ = Profile.objects.get_or_create(user=user)
            profile.role = role
            profile.display_name = display
            profile.save()
            users[username] = user

        author, _ = Author.objects.get_or_create(name="Marginalia Seed")
        series, _ = Series.objects.get_or_create(name="Field Notes")
        category, _ = Category.objects.get_or_create(
            name="Demo", defaults={"slug": "demo"}
        )

        books = {}
        for key, title, pages in [
            ("books/seed-handbook.pdf", "The Reading Handbook", 4),
            ("books/seed-notes.pdf", "Notes on Shared Margins", 3),
        ]:
            from apps.library.storage import get_storage

            storage = get_storage()
            pdf = _make_pdf(pages, title)
            if not storage.exists(key):
                storage.save(key, ContentFile(pdf))
            book, _ = Book.objects.get_or_create(
                file_path=key,
                defaults={
                    "title": title, "pages": pages, "file_size": len(pdf),
                    "description": "A seeded demo book with sample annotations.",
                    "language": "en",
                },
            )
            book.authors.add(author)
            book.series = series
            book.categories.add(category)
            book.save()
            books[title] = book

        handbook = books["The Reading Handbook"]
        notes = books["Notes on Shared Margins"]

        # Reading state + review
        ReadingProgress.objects.update_or_create(
            user=users["milo"], book=handbook,
            defaults={"last_position": 2, "percentage": 50.0},
        )
        Review.objects.update_or_create(
            user=users["noor"], book=handbook,
            defaults={"rating": 5, "review_text": "A lovely demo book."},
        )

        # A shared reading room with sample annotations + a reply thread.
        room, _ = ReadingRoom.objects.get_or_create(
            book=handbook, name="Handbook Club", owner=users["libby"],
            defaults={"is_active": True},
        )
        for user, role in [
            (users["libby"], RoomRole.OWNER),
            (users["milo"], RoomRole.EDITOR),
            (users["noor"], RoomRole.EDITOR),
        ]:
            RoomMember.objects.get_or_create(room=room, user=user, defaults={"role": role})
        room.rotate_invite()

        samples = [
            ("seed-root-1", "libby", 0, "markup", "",
             "Chapter one opens strong.", {"type": 8, "pageIndex": 0}),
            ("seed-reply-1", "milo", 0, "text_note", "seed-root-1",
             "Agreed — the pacing works.", {"type": 1, "pageIndex": 0,
                                            "inReplyToId": "seed-root-1", "replyType": "R"}),
            ("seed-root-2", "noor", 1, "ink", "",
             "Doodle in the margin.", {"type": 14, "pageIndex": 1}),
        ]
        for uid, who, page, subtype, parent, text, payload in samples:
            payload = dict(payload, id=uid, contents=text)
            Annotation.objects.update_or_create(
                book=handbook, room=room, uid=uid,
                defaults={
                    "author": users[who], "page_index": page, "subtype": subtype,
                    "parent_uid": parent, "text": text, "payload": payload,
                },
            )

        # A private annotation that must never leak into the room layer.
        Annotation.objects.update_or_create(
            book=notes, uid="seed-private-1", author=users["milo"],
            defaults={
                "page_index": 0, "subtype": "text_note", "text": "Private margin note.",
                "payload": {"id": "seed-private-1", "contents": "Private margin note."},
            },
        )

        # A private collection.
        collection, _ = Collection.objects.get_or_create(
            owner=users["milo"], name="Weekend Reads",
            defaults={"visibility": Visibility.PRIVATE},
        )
        collection.books.add(handbook, notes)

        self.stdout.write(self.style.SUCCESS(
            "Demo data ready. Logins (password demo-password-123): "
            "ada (admin), libby (librarian), milo/noor (members)."
        ))
